 let board=Array(81).fill("."), captures={X:0,O:0}, ko=null, events=[], history=[{n:0,board:board.slice(),captures:{...captures},ko}];
 function group(i){let stones=[],liberties=new Set(),seen=new Set([i]),q=[i];while(q.length){let k=q.pop();stones.push(k);for(let j of adj(k)){if(board[j]===".")liberties.add(j);else if(board[j]===board[i]&&!seen.has(j)){seen.add(j);q.push(j)}}}return {stones,liberties}}
 for(const m of log.moves){if(m.move==="pass"){ko=null;history.push({n:m.n,board:board.slice(),captures:{...captures},ko});continue;}let color=m.color==="B"?"X":"O", enemy=color==="X"?"O":"X",i=pos(m.move);if(board[i]!==".")throw Error("occupied "+m.n);if(i===ko)throw Error("ko "+m.n);board[i]=color;let removed=[];for(let j of adj(i)){if(board[j]!==enemy)continue;let g=group(j);if(!g.liberties.size){removed.push(...g.stones);g.stones.forEach(k=>board[k]=".")}}let own=group(i);if(!own.liberties.size)throw Error("suicide "+m.n);captures[color]+=removed.length;ko=removed.length===1&&own.stones.length===1&&own.liberties.size===1?removed[0]:null;
 if(removed.length)events.push({n:m.n,color:m.color,move:m.move,removed:removed.map(k=>cols[k%9]+(9-Math.floor(k/9))).sort()});
 history.push({n:m.n,board:board.slice(),captures:{...captures},ko});}
 let matches=[];
 for(const s of log.raw){let t=s.response.content.filter(c=>c.type==="text").map(c=>c.text).join("\n"),next=Number(t.match(/Move number: (\d+)/)[1]),n=next-1,state=history[n],actual=inspect(s.response),cap=t.match(/Captured by Black: (\d+); by White: (\d+)/),point=t.match(/Ko point: ([A-HJ][1-9]|none)/)[1];
